package com.travelbird.ai.service;
import com.travelbird.ai.dto.internal.PlaceSyncRequest;import com.travelbird.ai.dto.internal.PlaceSyncRequest.PlaceSyncItem;import com.travelbird.ai.repository.*;import java.time.*;import java.util.*;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component public class AiQueuedJobRecoveryWorker{private final AiQueuedJobReader jobs;private final AiRecommendationDataReader data;private final RecommendationSnapshotCodec snapshots;private final RecommendationPayloadFingerprint fingerprints;private final AiRecommendationDispatcher dispatcher;private final Clock clock;public AiQueuedJobRecoveryWorker(AiQueuedJobReader j,AiRecommendationDataReader d,RecommendationSnapshotCodec s,RecommendationPayloadFingerprint f,AiRecommendationDispatcher dispatcher,Clock c){jobs=j;data=d;snapshots=s;fingerprints=f;this.dispatcher=dispatcher;clock=c;}@Scheduled(fixedDelayString="${app.ai.queued-recovery-delay-ms:30000}")@Transactional(readOnly=true)public void redispatchQueuedJobs(){for(var job:jobs.queuedBefore(LocalDateTime.now(clock).minusSeconds(5))){var request=snapshots.read(job);Set<Long> ids=new LinkedHashSet<>(request.savedPlaceIds());ids.addAll(request.wishlistPlaceIds());request.existingSchedule().forEach(day->ids.addAll(day.placeIds()));var items=data.places(ids).stream().map(p->new PlaceSyncItem(p.getId(),p.getRegion().getSigunguCode(),p.getName(),p.getAddress(),p.getLatitude(),p.getLongitude(),p.getCategory())).toList();dispatcher.dispatchSafely(new AiDispatchRequested(request,new PlaceSyncRequest(items),fingerprints.sha256(request)));}}}
